"""Package the original WAV bytes for file:// playback; no dependencies."""
import base64
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
FILES = [f"assets/drums/{name}.wav" for name in ("kick", "snare", "hat", "tom")]
OUTPUT = ROOT / "assets/drums/embedded.js"
data = {name: base64.b64encode((ROOT / name).read_bytes()).decode("ascii") for name in FILES}
content = (
    "// Generated by python scripts/build-embedded.py; do not edit manually.\n"
    "// Original WAV bytes: Michael Fischer / Technopolis TR-808, CC0.\n"
    "// See CC0.txt and SOURCE-README.txt in this directory.\n"
    "globalThis.HelloDrumSamples = Object.freeze("
    + json.dumps(data, indent=2)
    + ");\n"
)
if "--check" in sys.argv:
    if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != content:
        sys.exit("FAIL: embedded.js differs from the original WAV files; regenerate it.")
    print("PASS: embedded.js matches all four original WAV files")
else:
    OUTPUT.write_text(content, encoding="utf-8")
    print("Generated assets/drums/embedded.js")
